    {
      "column": "Quality of Life Scale",
      "definition": "What Quality of Life (QoL) or Patient-Reported Outcome (PRO) scales were used in the trial? List the full names of the validated instruments, including version numbers or specific sub-scales (e.g., 'Brief Pain Inventory Short-Form'), separated by commas. Use 'Not reported' if no scales are identified.",
      "change": "Specified that full names, version numbers, and sub-scales must be included, and that multiple scales should be comma-separated."
    },
    {
      "column": "Mode of metastases - N (%) | Synchronous | Treatment",
      "definition": "What is the count and percentage of patients in the treatment arm who had synchronous (de novo) metastatic disease at diagnosis? Include the value as stated (e.g., '558 (85.7%)'). Include the paper's label only if it uses a non-standard term for synchronous disease (e.g., 'De novo metastatic at diagnosis'). Use 'Not reported' if the count/percentage is not available.",
      "change": "Refined the rule for including labels: only include the label if the paper uses a non-standard term, otherwise provide just the count/percentage."
    },
    {
      "column": "Mode of metastases - N (%) | Synchronous | Control",
      "definition": "What is the count and percentage of patients in the control arm who had synchronous (de novo) metastatic disease at diagnosis? Include the value as stated (e.g., '566 (86.5%)'). Include the paper's label only if it uses a non-standard term for synchronous disease. Use 'Not reported' if the count/percentage is not available.",
      "change": "Refined the rule for including labels: only include the label if the paper uses a non-standard term, otherwise provide just the count/percentage."
    },
    {
      "column": "Mode of metastases - N (%) | Metachronous | Treatment",
